\subsection{Background}
Charles Ehresmann defined in 1963 a {\em double category} $\mathcal{D}$ as an internal category in the category of small categories $\bf{Cat}$.
\subsection{Double category definition} \begin{definition} A double category $\mathcal{D}$ consists of: \begin{itemize} \item a set of objects, \item a set of horizontal morphisms $$f: A \to B$$, \item a set of vertical morphisms $$j: A \to C$$, and \item a class of squares with source and target as shown in the following diagrams: $$\xymatrix{ {A}\ar[r]^{f}\ar[d]_{k}&{B}\ar[d]^{g}\\ {C}\ar[r]_{h}&{D} } $$ \end{itemize}
with compositions and units of the double category that satisfy the following axioms: \begin{itemize} \item \emph{i.} Horizontal: \[ A\buildrel f_1 \over \longrightarrow B \buildrel f_2 \over \longrightarrow C = [f_1, f_2]= f_2 \circ f_1 \]
\[ A\buildrel 1^h_A \over \longrightarrow A \buildrel f_1 \over \longrightarrow B = A\buildrel f_1 \over \longrightarrow B = A \buildrel f_1 \over \longrightarrow B \buildrel 1^h_B \over \longrightarrow B \]
\item \emph{ii.} Vertical: \[ [A\buildrel j_1 \over \longrightarrow B \buildrel j_2 \over \longrightarrow C]_{vert} = [j_1, j_2]_{vert.}= j_2 \circ j_1 \]
\[ [A\buildrel 1^v_A \over \longrightarrow A \buildrel j_1 \over \longrightarrow B = A\buildrel j_1 \over \longrightarrow B = A \buildrel j_1 \over \longrightarrow B \buildrel 1^v_B \over \longrightarrow B]_{vert.} \] \emph{Compositions for square diagrams in a double category $\mathcal{D}$:} \item \emph{iii.} Horizontal composition: $$\xymatrix{ {A}\ar[r]^{f_1}\ar[d]_{j}&{B}\ar[d]^{k}\\ {D}\ar[r]_{g_1}&{E}}~~~~[\alpha]``\circ'' \xymatrix{ {B}\ar[r]^{f_2}\ar[d]_{k}&{C}\ar[d]^{l}\\ {E}\ar[r]_{g_2}&{F}}~~~~[\beta] = \xymatrix{ {A}\ar[r]^{[f_1f_2]}\ar[d]_{j}&{C}\ar[d]^{l}\\ {D}\ar[r]_{g_1g_2}&{F}} ~~~~[\alpha \beta].$$ \item \emph{iv.} Vertical composition of squares in $\mathcal{D}$: ${[\alpha \beta]}_{vert.}$ is expressed as $$\xymatrix{ {A}\ar[r]^{f}\ar[d]_{[j_1 j_2]_v}&{B}\ar[d]^{[k_1 k_2]_v}\\ {E}\ar[r]_{h}&{F}}~~~~[\alpha \beta].$$ \end{itemize}
\end{definition}
